/*
 * Export tables generated by uglyModule (Template Haskell), until the
 * plugin joins the conformance suite: the test module Example, whose
 * types get instances and methods, and whose polymorphic functions (classes
 * with one parameter, and with two and a functional dependency) are
 * overloads chosen by their arguments.
 */
#include "tap.h"

static ugly_handle mod, smoke ;

/* Calls member 'name' of m with args, as 'want'. */
static ugly_status call(ugly_handle m, const char *name, const ugly_val *args, size_t nargs, ugly_kind want,
	ugly_val *out){
	*out = ugly_null() ;
	return ugly_invoke(ctx, m, name, args, nargs, want, out) ;
}

/* The text of h (want STRING, through Smoke.identity) is s. */
static int text_is(ugly_handle h, const char *s){
	ugly_val t = ugly_null() ;
	int good = (call(smoke, "identity", (ugly_val[]){ ugly_hval(h) }, 1, UGLY_STRING, &t) == UGLY_OK)&&is_string(t, s) ;
	if (! good){
		printf("# text: %.*s\n", t.kind == UGLY_STRING ? (int)t.as.str.len : 0, t.kind == UGLY_STRING ? t.as.str.ptr : "") ;
	}
	ugly_val_release(ctx, &t) ;
	return good ;
}

static ugly_status inc_fn(ugly_ctx *c, void *data, const ugly_val *args, size_t nargs, ugly_kind want, ugly_val *out){
	(void)c ; (void)data ; (void)nargs ; (void)want ;
	*out = ugly_int(args[0].as.i + 1) ;
	return UGLY_OK ;
}

int main(void){
	ugly_rt *rt = start("Example", &mod) ;
	ugly_val v, w ;
	ugly_handle h, circle, pt, primes ;
	int64_t len ;
	ugly_rt_import(ctx, rt, "Smoke", &smoke) ;

	ok((ugly_member_names(ctx, mod, &h) == UGLY_OK)&&(ugly_length(ctx, h, &len) == UGLY_OK)&&(len == 11),
		"uglyModule: the 11 values listed (types aren't members)") ;
	ugly_release(ctx, h) ;

	/* Listed types get instances: a box, its show, its methods. */
	ugly_get_member(ctx, mod, "origin", UGLY_ANY, &v) ;
	ok((v.kind == UGLY_HANDLE)&&type_is(v.as.h, 0, "Pt")&&text_is(v.as.h, "Pt 0 0"), "origin: a Pt, shown Pt 0 0") ;
	ugly_val_release(ctx, &v) ;
	ok((call(mod, "Circle", (ugly_val[]){ ugly_double(2.0) }, 1, UGLY_ANY, &v) == UGLY_OK)&&(v.kind == UGLY_HANDLE)
		&&type_is(v.as.h, 0, "Shape")&&text_is(v.as.h, "Circle 2.0"), "Circle 2.0: a constructor is a function") ;
	circle = v.as.h ;
	ok((call(mod, "Circle", (ugly_val[]){ ugly_int(1) }, 1, UGLY_ANY, &v) == UGLY_OK)&&text_is(v.as.h, "Circle 1.0"),
		"Circle 1: an int is a Double") ;
	ugly_val_release(ctx, &v) ;
	ok((call(mod, "Pt", (ugly_val[]){ ugly_int(3), ugly_int(4) }, 2, UGLY_ANY, &v) == UGLY_OK)&&text_is(v.as.h, "Pt 3 4"),
		"Pt 3 4") ;
	pt = v.as.h ;

	/* A class with one parameter: one overload per instance. */
	ugly_get_member(ctx, mod, "area", UGLY_ANY, &v) ;
	ok(type_is(v.as.h, UGLY_TRAIT_CALLABLE, "area :: HasArea a => a -> Double"), "area: its polymorphic type") ;
	ugly_val_release(ctx, &v) ;
	ok((call(mod, "area", (ugly_val[]){ ugly_hval(circle) }, 1, UGLY_ANY, &v) == UGLY_OK)&&(v.kind == UGLY_DOUBLE)
		&&(v.as.d > 12.56)&&(v.as.d < 12.57), "area (Circle 2.0): the Shape instance, 4 pi") ;
	ok((call(mod, "area", (ugly_val[]){ ugly_hval(pt) }, 1, UGLY_ANY, &v) == UGLY_OK)&&(v.as.d == 0.0),
		"area (Pt 3 4): the Pt instance, 0") ;
	ok(error_is(call(mod, "area", (ugly_val[]){ ugly_int(5) }, 1, UGLY_ANY, &v), UGLY_ERR_TYPE, "TypeError",
		"no instance of area"), "area 5: TYPE, no instance") ;
	ok((call(mod, "scale", (ugly_val[]){ ugly_int(2), ugly_hval(pt) }, 2, UGLY_ANY, &v) == UGLY_OK)
		&&text_is(v.as.h, "Pt 6 8"), "scale 2 (Pt 3 4): Pt 6 8") ;
	ugly_val_release(ctx, &v) ;

	/* Two parameters and a functional dependency: the result's type follows. */
	ok((call(mod, "unit", (ugly_val[]){ ugly_hval(circle) }, 1, UGLY_ANY, &v) == UGLY_OK)&&is_string(v, "m2"),
		"unit (Circle 2.0): a String, m2") ;
	ugly_val_release(ctx, &v) ;
	ok((call(mod, "unit", (ugly_val[]){ ugly_hval(pt) }, 1, UGLY_ANY, &v) == UGLY_OK)&&is_int(v, 3),
		"unit (Pt 3 4): an Int, 3") ;

	/* Methods: the module's functions, the receiver last. */
	ok((ugly_invoke(ctx, pt, "scale", (ugly_val[]){ ugly_double(0.5) }, 1, UGLY_ANY, &v) == UGLY_OK)
		&&text_is(v.as.h, "Pt 2 2"), "pt.scale(0.5): scale 0.5 pt, Pt 2 2 (rounded)") ;
	ugly_val_release(ctx, &v) ;
	ok((ugly_invoke(ctx, circle, "area", NULL, 0, UGLY_ANY, &v) == UGLY_OK)&&(v.as.d > 12.56), "circle.area()") ;
	ugly_handle inc ;
	ugly_callable_new(ctx, inc_fn, NULL, NULL, &inc) ;
	ok((ugly_invoke(ctx, pt, "mapPt", (ugly_val[]){ ugly_hval(inc) }, 1, UGLY_ANY, &v) == UGLY_OK)
		&&text_is(v.as.h, "Pt 4 5"), "pt.mapPt(inc): a callback, a C callable as an Int -> Int, Pt 4 5") ;
	ugly_val_release(ctx, &v) ;
	ugly_release(ctx, inc) ;
	ok((ugly_invoke(ctx, circle, "label", (ugly_val[]){ ugly_str("c", 1) }, 1, UGLY_ANY, &v) == UGLY_OK)
		&&is_string(v, "c: Circle 2.0"), "circle.label(\"c\"): label \"c\" circle") ;
	ugly_val_release(ctx, &v) ;

	/* Polymorphic over a base class (Ord, Show): the instantiations whose types can cross. */
	ugly_get_member(ctx, smoke, "primes", UGLY_HANDLE, &w) ;
	primes = w.as.h ;
	ok((call(mod, "largest", (ugly_val[]){ ugly_hval(primes) }, 1, UGLY_ANY, &v) == UGLY_OK)&&is_int(v, 11),
		"largest primes: the [Int] instance, 11 (a value from another module comes home)") ;
	ok((call(mod, "label", (ugly_val[]){ ugly_str("n", 1), ugly_int(5) }, 2, UGLY_ANY, &v) == UGLY_OK)
		&&is_string(v, "n: 5"), "label \"n\" 5: an int is an Int first") ;
	ugly_val_release(ctx, &v) ;
	ok((call(mod, "label", (ugly_val[]){ ugly_str("s", 1), ugly_str("x", 1) }, 2, UGLY_ANY, &v) == UGLY_OK)
		&&is_string(v, "s: \"x\""), "label \"s\" \"x\": a string is a String first") ;
	ugly_val_release(ctx, &v) ;

	/* An unconstrained [a] is [Value]: any sequence, through its elements. */
	ok((call(mod, "firstOf", (ugly_val[]){ ugly_hval(primes) }, 1, UGLY_ANY, &v) == UGLY_OK)&&is_int(v, 2),
		"firstOf primes: 2") ;
	ugly_get_member(ctx, smoke, "colors", UGLY_HANDLE, &w) ;
	ok((call(mod, "firstOf", &w, 1, UGLY_STRING, &v) == UGLY_OK)&&is_string(v, "Red"), "firstOf colors: Red") ;
	ugly_val_release(ctx, &v) ;
	ugly_val_release(ctx, &w) ;

	ugly_release(ctx, primes) ;
	ugly_release(ctx, circle) ;
	ugly_release(ctx, pt) ;
	ugly_release(ctx, smoke) ;
	ugly_release(ctx, mod) ;
	ok(ugly_rt_delete(ctx, rt) == UGLY_OK, "runtime deleted") ;
	all_released() ;
	ugly_ctx_delete(ctx) ;
	printf("1..%d\n", n) ;
	return failed ;
}
